// Spec: 02-foundations-3 §F29 (token files), 02 F1–F8, 02-2 F11.2, F12.2, F25.4–F25.5, 08-0 §E.1.
// design/tokens.json (the only hand-edited style source) → src/renderer/styles/tokens.css,
// src/shared/tokens.ts and design/tokens.paper.json. Never edit the generated files.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

type Token = { $type: string; $value: unknown; $description?: string; $extensions?: { foo?: { modes?: { dark?: unknown } } } };
type Flat = { path: string[]; name: string; token: Token };

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const BANNER = 'GENERATED by scripts/build-tokens.ts from design/tokens.json. Do not edit.';

export function flatten(tree: Record<string, unknown>, path: string[] = []): Flat[] {
  const out: Flat[] = [];
  for (const [key, node] of Object.entries(tree)) {
    const p = [...path, key];
    if (node && typeof node === 'object' && '$value' in node) out.push({ path: p, name: cssName(p), token: node as Token });
    else if (node && typeof node === 'object') out.push(...flatten(node as Record<string, unknown>, p));
  }
  return out;
}

/** F29.1 naming: `--{group}-{role}`; `default` leaf = the group itself; spacing is `--s` + step; sizes are bare nouns. */
export function cssName(path: string[]): string {
  const [group, ...rest] = path;
  if (group === 's') return `--s${rest[0]}`;
  if (group === 'size') return `--${rest.join('-')}`;
  const tail = rest.filter((r) => r !== 'default');
  return `--${[group, ...tail].join('-')}`;
}

const rem = (px: string) => `${+(parseFloat(px) / 16).toFixed(4)}rem`;

function ref(v: unknown, byPath: Map<string, Flat>): string {
  if (typeof v === 'string' && /^\{.+\}$/.test(v)) {
    const target = byPath.get(v.slice(1, -1));
    if (!target) throw new Error(`Unknown token reference ${v}`);
    return `var(${target.name})`;
  }
  return String(v);
}

function cssValue(f: Flat, v: unknown, byPath: Map<string, Flat>): string {
  const t = f.token.$type;
  if (t === 'cubicBezier') return `cubic-bezier(${(v as number[]).join(', ')})`;
  if (t === 'dimension' && f.path[0] === 's') return `${rem(String(v))}`;
  return ref(v, byPath);
}

export function buildCss(tree: Record<string, unknown>): string {
  const flat = flatten(tree);
  const byPath = new Map(flat.map((f) => [f.path.join('.'), f]));
  const light: string[] = [];
  const dark: string[] = [];
  const bp: string[] = [];
  for (const f of flat) {
    const t = f.token;
    if (f.path[0] === 'bp') {
      bp.push(`${f.name}: ${t.$value}`);
      continue;
    }
    if (t.$type === 'typography') {
      const v = t.$value as { fontFamily: string; fontSize: string; lineHeight: string; fontWeight: number; letterSpacing: string };
      light.push(`${f.name}-size: ${rem(v.fontSize)}; /* ${v.fontSize} */`);
      light.push(`${f.name}-lh: ${rem(v.lineHeight)}; /* ${v.lineHeight} */`);
      light.push(`${f.name}-weight: ${v.fontWeight};`);
      light.push(`${f.name}-tracking: ${v.letterSpacing};`);
      light.push(`${f.name}: ${v.fontWeight} var(${f.name}-size)/var(${f.name}-lh) ${ref(v.fontFamily, byPath)};`);
      continue;
    }
    if (t.$type === 'fontFamily') {
      // F1: Segoe UI Emoji is appended to every text stack.
      const v = f.path[1] === 'emoji' ? String(t.$value) : `${t.$value}, var(--font-emoji)`;
      light.push(`${f.name}: ${v};`);
      continue;
    }
    const px = t.$type === 'dimension' && f.path[0] === 's' ? ` /* ${t.$value} */` : '';
    light.push(`${f.name}: ${cssValue(f, t.$value, byPath)};${px}`);
    const d = t.$extensions?.foo?.modes?.dark;
    if (d !== undefined) dark.push(`${f.name}: ${cssValue(f, d, byPath)};`);
  }
  const ind = (l: string[]) => l.map((x) => `  ${x}`).join('\n');
  // F7 + F25.4: reduced motion / "Off": fades ≤ 83ms, no movement, no shimmer.
  const reduced = [
    '--m-normal: 83ms;',
    '--m-slow: 83ms;',
    '--m-card: 83ms;',
    '--m-basic: 83ms;',
    '--m-shimmer: 0ms;',
    '--m-face-cross: 83ms;',
    '--m-spring: 83ms;',
    '--m-stagger: 0ms;',
    '--m-breathe: 0ms;',
    '--ease-spring: var(--ease-in);',
    '--ease-spring-soft: var(--ease-in);',
    '--motion-move: 0;',
  ];
  // F7 X-150 "Basic": fades only, 200ms basic curve, no movement.
  const basic = [
    '--m-fast: var(--m-basic);',
    '--m-normal: var(--m-basic);',
    '--m-slow: var(--m-basic);',
    '--m-card: var(--m-basic);',
    '--ease-in: var(--ease-basic);',
    '--ease-out: var(--ease-basic);',
    '--ease-standard: var(--ease-basic);',
    '--m-spring: var(--m-basic);',
    '--m-stagger: 0ms;',
    '--m-breathe: 0ms;',
    '--ease-spring: var(--ease-basic);',
    '--ease-spring-soft: var(--ease-basic);',
    '--m-shimmer: 0ms;',
    '--motion-move: 0;',
  ];
  // F25.5 contrast themes mapping.
  const forced = [
    ...['--bg-app', '--bg-sidebar', '--bg-raised', '--bg-sunken', '--bg-selected', '--bubble-me', '--bubble-foo', '--qr-bg'].map(
      (n) => `${n}: Canvas;`,
    ),
    ...['--bg-hover', '--bg-pressed', '--accent-soft', '--info-soft'].map((n) => `${n}: Highlight;`),
    ...[
      '--fg-1',
      '--fg-2',
      '--fg-3',
      '--on-bubble-foo',
      '--on-bubble-me',
      '--on-bubble-me-2',
      '--ok',
      '--warn',
      '--bad',
      '--live',
      '--line',
      '--line-strong',
      '--line-input',
      '--qr-fg',
    ].map((n) => `${n}: CanvasText;`),
    '--fg-disabled: GrayText;',
    '--accent: ButtonText;',
    '--accent-hover: ButtonText;',
    '--accent-pressed: ButtonText;',
    '--on-accent: ButtonFace;',
    '--info: ButtonText;',
    '--tick-read: CanvasText;',
    '--tick-read-on-me: CanvasText;',
    '--focus-outer: Highlight;',
    '--focus-inner: Canvas;',
    ...['--shadow-1', '--shadow-4', '--shadow-16', '--shadow-28', '--media-scrim'].map((n) => `${n}: none;`),
    '--scrim: Canvas;',
  ];
  return `/* ${BANNER} */
/* Breakpoints (02-2 F11.2; build-time constants, only these may appear in queries): ${bp.join(', ')} */
:root {
  color-scheme: light;
  --motion-move: 1;
${ind(light)}
}
[data-theme='dark'] {
  color-scheme: dark;
${ind(dark)}
}
@media (prefers-reduced-motion: reduce) {
  :root {
${reduced.map((x) => `    ${x}`).join('\n')}
  }
}
:root[data-motion='off'] {
${ind(reduced)}
}
:root[data-motion='basic'] {
${ind(basic)}
}
@media (forced-colors: active) {
  :root,
  [data-theme='dark'] {
${forced.map((x) => `    ${x}`).join('\n')}
  }
}
`;
}

export function buildTs(tree: Record<string, unknown>): string {
  const flat = flatten(tree);
  const byPath = new Map(flat.map((f) => [f.path.join('.'), f]));
  const resolve = (v: unknown): unknown =>
    typeof v === 'string' && /^\{.+\}$/.test(v) ? resolve(byPath.get(v.slice(1, -1))!.token.$value) : v;
  const num = (v: unknown) => parseFloat(String(resolve(v)));
  const pick = (g: string) => flat.filter((f) => f.path[0] === g);
  const obj = (entries: [string, unknown][]) => Object.fromEntries(entries);
  const motion = obj([
    ...pick('m').map((f) => [f.path.slice(1).join('-'), num(f.token.$value)] as [string, unknown]),
    ...pick('delay').map((f) => [`delay-${f.path.slice(1).join('-')}`, num(f.token.$value)] as [string, unknown]),
    ...pick('dur').map((f) => [`dur-${f.path.slice(1).join('-')}`, num(f.token.$value)] as [string, unknown]),
    ...pick('ease').map(
      (f) =>
        [
          `ease-${f.path[1]}`,
          f.token.$type === 'cubicBezier' ? `cubic-bezier(${(f.token.$value as number[]).join(', ')})` : String(f.token.$value),
        ] as [string, unknown],
    ),
  ]);
  const bp = obj(pick('bp').map((f) => [f.path[1]!, num(f.token.$value)]));
  const z = obj(pick('z').map((f) => [f.path[1]!, num(f.token.$value)]));
  const size = obj(pick('size').map((f) => [f.path[1]!, num(f.token.$value)]));
  const colors = obj(
    flat
      .filter((f) => f.token.$type === 'color')
      .map((f) => [f.name, { light: resolve(f.token.$value), dark: resolve(f.token.$extensions?.foo?.modes?.dark ?? f.token.$value) }]),
  );
  const j = (v: unknown) => JSON.stringify(v, null, 2);
  return `// ${BANNER}
export const tokens = { colors: ${j(colors)}, size: ${j(size)} } as const;
export const motion = ${j(motion)} as const;
export const bp = ${j(bp)} as const;
export const z = ${j(z)} as const;
`;
}

export function buildPaper(tree: Record<string, unknown>): string {
  const flat = flatten(tree);
  return (
    JSON.stringify(
      Object.fromEntries(
        flat.map((f) => [
          f.name,
          { type: f.token.$type, light: f.token.$value, dark: f.token.$extensions?.foo?.modes?.dark ?? f.token.$value },
        ]),
      ),
      null,
      2,
    ) + '\n'
  );
}

export function readTree(): Record<string, unknown> {
  return JSON.parse(readFileSync(join(ROOT, 'design/tokens.json'), 'utf8'));
}

export const OUTPUTS = {
  css: 'src/renderer/styles/tokens.css',
  ts: 'src/shared/tokens.ts',
  paper: 'design/tokens.paper.json',
} as const;

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const tree = readTree();
  writeFileSync(join(ROOT, OUTPUTS.css), buildCss(tree));
  writeFileSync(join(ROOT, OUTPUTS.ts), buildTs(tree));
  writeFileSync(join(ROOT, OUTPUTS.paper), buildPaper(tree));
  console.log('tokens built');
}
